    solid: ["bg-balsa-info", "text-balsa-info-foreground"],
    soft: ["bg-balsa-info/15", "text-balsa-info"],
    outline: ["border-balsa-info", "text-balsa-info"],
    glass: ["border-balsa-info/40", "bg-balsa-info/10", "text-balsa-info", "backdrop-balsa"],
  },
